from pathlib import Path
import os, re, urllib.request, urllib.error
p = Path('/data/.env')
if not p.exists():
    print('RESULT=ENV_FILE_NOT_FOUND')
    raise SystemExit(0)
text = p.read_text(encoding='utf-8')
key = None
source = None
for name in ('OPENAI_API_KEY', 'VOICE_TOOLS_OPENAI_KEY'):
    m = re.search(rf'^\s*(?:export\s+)?{name}\s*=\s*["\']?([^\s"\'#]+)', text, re.M)
    if m:
        key, source = m.group(1), name
        break
if not key:
    print('RESULT=KEY_NOT_CONFIGURED')
    raise SystemExit(0)
request = urllib.request.Request(
    'https://api.openai.com/v1/models',
    headers={'Authorization': f'Bearer {key}'}
)
try:
    with urllib.request.urlopen(request, timeout=20) as response:
        print(f'RESULT=VALID;SOURCE={source};HTTP={response.status}')
except urllib.error.HTTPError as exc:
    print(f'RESULT=REJECTED;SOURCE={source};HTTP={exc.code}')
except Exception as exc:
    print(f'RESULT=CONNECTION_ERROR;TYPE={type(exc).__name__}')
